('69bd6fa1-7ed9-5783-89b6-c7cbbc12277e', (select id from categories where slug = 'sinema'), 'ku-kmr', 'Di fîlmê "Zare" de Saydo, dergistiyê Zareyê, bi kîjan karî debara xwe dike?', 'Aşvan', 'Şivan', 'Hesinkar', 'Bazirgan', 'B', 'Çîrok evîna du ciwanên êzîdî, şivan Saydo û Zareyê, vedibêje. Timûr-beg jî dixwaze Zareyê ji Saydoyî bistîne.', 'Çîrok evîna du ciwanên êzîdî, şivan Saydo û Zareyê, vedibêje. Timûr-beg jî dixwaze Zareyê ji Saydoyî bistîne.', 'Hikâye iki genç Ezidi''nin, çoban Saydo ile Zare''nin aşkını anlatır. Timur Bey de Zare''yi Saydo''dan koparmak ister.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Zare_(film)', 'Zare (film) - Wikipedia', 'https://en.wikipedia.org/wiki/Zare_(film)', 'approved', 'Kurmancî', 2, now()),
('d9ca3a76-107e-5400-8382-54f5d8fcc1cb', (select id from categories where slug = 'sinema'), 'ku-kmr', 'Fîlmê "Zare" (1926), ku li Ermenistana Sovyetê hat çêkirin, kê nivîsî û kişand?', 'Rouben Mamoulian', 'Sergei Parajanov', 'Sergei Eisenstein', 'Hamo Beknazarian', 'D', 'Hamo Beknazarian (Bek-Nazarov) ji Yêrêvanê bû û "Zare" hem nivîsî hem kişand; yekem berhema dengdar a ermenî, "Pepo", jî wî kişand.', 'Hamo Beknazarian (Bek-Nazarov) ji Yêrêvanê bû û "Zare" hem nivîsî hem kişand; yekem berhema dengdar a ermenî, "Pepo", jî wî kişand.', 'Erivanlı Hamo Beknazarian (Bek-Nazarov) "Zare"yi hem yazdı hem çekti; ilk sesli Ermeni yapımı "Pepo"yu da o çekti.', 3, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Zare_(film)', 'Zare (film) - Wikipedia', 'https://en.wikipedia.org/wiki/Zare_(film)', 'approved', 'Kurmancî', 2, now()),
